68	// Real libc entry points provided by the --wrap linker mechanism.
69	int __real_open(const char* path, int flags, ...);
70	ssize_t __real_write(int fd, const void* buffer, size_t count);
71	int __real_fsync(int fd);
72	int __real_close(int fd);
