76	constexpr std::size_t kKeyBytes = 32;
77	
78	// Descriptor currently known to belong to the key file under test, or -1.
79	int g_keyFd = -1;
80	
81	// Continuity bookkeeping for EF_TEST_WRITE_LOG.
82	unsigned char g_keySnapshot[kKeyBytes];
83	bool g_haveSnapshot = false;     // the snapshot below is valid
84	std::size_t g_progress = 0;      // bytes acknowledged so far (pre-call offset)
85	
86	bool envFlagSet(const char* name) {
87	    const char* value = std::getenv(name);
88	    return value != nullptr && value[0] != '\0' && std::strcmp(value, "0") != 0;
89	}
