100	// Preserve errno across the bookkeeping I/O so the injected failure code is
101	// what the product code actually observes.
102	class ErrnoSaver {
103	public:
104	    ErrnoSaver() : saved_(errno) {}
105	    ~ErrnoSaver() { errno = saved_; }
106	
107	private:
108	    int saved_;
109	};
110	
111	void logLine(const char* mode, const char* text) {
112	    const char* logPath = std::getenv("EF_TEST_WRITE_LOG");
113	    if (logPath == nullptr || logPath[0] == '\0') {
114	        return;
115	    }
116	    ErrnoSaver saver;
117	    std::FILE* file = std::fopen(logPath, mode);
118	    if (file == nullptr) {
119	        return;
120	    }
121	    std::fputs(text, file);
122	    std::fputc('\n', file);
123	    std::fclose(file);
124	}
125	
126	void logVerifyHeader(const unsigned char* buffer) {
127	    constexpr std::size_t kPrefix = 7;  // strlen("VERIFY ")
128	    char line[kPrefix + 2 * kKeyBytes + 1];
129	    char* out = line;
130	    std::strcpy(out, "VERIFY ");
131	    out += 7;
132	    static const char hex[] = "0123456789abcdef";
133	    for (std::size_t i = 0; i < kKeyBytes; ++i) {
134	        *out++ = hex[buffer[i] >> 4];
135	        *out++ = hex[buffer[i] & 0x0f];
136	    }
137	    *out = '\0';
138	    logLine("w", line);
139	}
140	
141	void logCall(std::size_t offset, std::size_t requested,
142	             ssize_t returned, int reportedErrno) {
143	    char line[128];
144	    if (returned < 0) {
145	        std::snprintf(line, sizeof(line), "CALL %zu %zu %zd %d",
146	                      offset, requested, returned, reportedErrno);
147	    } else {
148	        std::snprintf(line, sizeof(line), "CALL %zu %zu %zd",
149	                      offset, requested, returned);
150	    }
151	    logLine("a", line);
152	}
153	
154	void logVerifyFailed(const char* reason) {
155	    char line[160];
156	    std::snprintf(line, sizeof(line), "VERIFY-FAILED %s", reason);
157	    logLine("a", line);
158	}
159	
160	// On the first key-file write, snapshot the key; afterwards confirm that the
161	// caller resumes exactly at the acknowledged offset and presents the matching
162	// slice of the same key. Any mismatch is a product-code defect: abort so the
163	// regression run can never pass on a silently regenerated/garbled key.
164	void verifyIncomingBuffer(const void* buffer, std::size_t count) {
165	    if (std::getenv("EF_TEST_WRITE_LOG") == nullptr) {
166	        return;
167	    }
168	    const auto* bytes = static_cast<const unsigned char*>(buffer);
169	    if (!g_haveSnapshot) {
170	        if (count != kKeyBytes) {
171	            logVerifyFailed("first write did not carry the whole 32-byte key");
172	            std::abort();
173	        }
174	        std::memcpy(g_keySnapshot, bytes, kKeyBytes);
175	        g_haveSnapshot = true;
176	        logVerifyHeader(g_keySnapshot);
177	        return;
178	    }
179	    if (g_progress > kKeyBytes) {
180	        logVerifyFailed("offset past end of key");
181	        std::abort();
182	    }
183	    const std::size_t remaining = kKeyBytes - g_progress;
184	    if (count != remaining) {
185	        logVerifyFailed("write length does not match the bytes still pending");
186	        std::abort();
187	    }
188	    if (std::memcmp(g_keySnapshot + g_progress, bytes, remaining) != 0) {
189	        logVerifyFailed("buffer is not the same key (key was regenerated?)");
190	        std::abort();
191	    }
192	}
193	
194	void resetWriteBookkeeping() {
195	    g_haveSnapshot = false;
196	    g_progress = 0;
197	}
198	
199	// Outcome of one scripted write() call.
200	enum class WriteOutcome {
201	    kPass,       // behave as the real syscall with the given count
202	    kShort,      // behave as the real syscall but cap the count
203	    kEintr,      // report a recoverable interrupt, nothing written
204	    kEio,        // report an irrecoverable I/O error
205	    kZero,       // report zero bytes with data still pending
206	};
207	
208	struct ScriptedCall {
209	    WriteOutcome outcome;
210	    long limit;  // valid for kShort
211	};
